-- Payroll statutory documents (SCRUM-571, the company payroll's R6):
-- docs/progress/plans/payroll-real-build/PLAN.md §1 and §9 R6, with owner
-- decision 3 (2026-10-20): the statutory documents are built exactly as the
-- prototype has them. They read the OLDER per-branch locked runs; a company
-- month-end lock writes none, so on this data no document has a source and
-- the page says so. Nothing here connects company snapshots to them.
--
-- Generated by drizzle-kit from shared/schema.ts and hand-edited as 0021-0025
-- are: re-runnable, the public-schema qualifier stripped, parent keys before
-- the foreign keys that use them. Expand-only.
--
--   - payroll_statutory_documents: a rendered document (the engine's
--     printable HTML and its placeholder upload), with its source runs,
--     coverage, warnings and due date. Only ever written from a locked source.
--   - payroll_statutory_filings: a filing record — form, period, filed on,
--     reference, reason, who, and the coverage state when it was saved
--     (complete / provisional / no-source); against a rendered document at
--     most once, or for a form filed outside the app.
--   - payroll_statutory_audit: every document and filing event.
--
-- All three are append-only: R4's trigger function payroll_frozen_rows()
-- (0025) refuses UPDATE and DELETE. Nothing is seeded and no row is added to an
-- older table.
CREATE TABLE IF NOT EXISTS "payroll_statutory_documents" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"branch_id" varchar NOT NULL,
	"period" text NOT NULL,
	"document_code" text NOT NULL,
	"document_key" text NOT NULL,
	"staff_id" varchar,
	"title" text NOT NULL,
	"source_runs" jsonb NOT NULL,
	"provisional" boolean NOT NULL,
	"coverage" jsonb NOT NULL,
	"warnings" jsonb NOT NULL,
	"due_date" date NOT NULL,
	"html" text NOT NULL,
	"files" jsonb NOT NULL,
	"sha256" text NOT NULL,
	"rendered_at" timestamp with time zone DEFAULT now() NOT NULL,
	"rendered_by" varchar,
	"rendered_by_name" text NOT NULL,
	CONSTRAINT "payroll_statutory_documents_period_check" CHECK ("payroll_statutory_documents"."period" ~ '^[0-9]{4}(-(0[1-9]|1[0-2]))?$')
);
--> statement-breakpoint
